/* From Uiverse.io by 1osm - Tags: card */
.__UIV_SCOPE__ .card {
  width: 200px;
  height: 250px;
  background: #262626;
}

.__UIV_SCOPE__ .GameIcon {
  transform: translate(-80px,-50px);
  position: absolute;
  width: 200px;
  height: 200px;
  transition: 0.3s;
}

.__UIV_SCOPE__ .GameImg {
  width: 100%;
  height: 100%;
}

.__UIV_SCOPE__ .Gfooter {
  width: 100%;
  height: 0%;
  background-color: #262626;
  border-radius: 10px;
  transition: all 0.3s;
}

.__UIV_SCOPE__ .Name {
  transform: translate(10px,200px);
  position: absolute;
  background-color: transparent;
  font-weight: bold;
  font-size: 18px;
  transition: 0.3s;
  color: #ff5858;
}

.__UIV_SCOPE__ .SmallIcon {
  width: 0px;
  height: 0px;
  transform: translate(10px,10px);
  border-radius: 10px;
  background-color: #ff5858;
  transition: 0.2s;
}

.__UIV_SCOPE__ .Descripion {
  padding: 10px;
  position: absolute;
  transform: translate(0px,20px);
  opacity: 0%;
  color: #ff5858;
  font-weight: bold;
  font-size: 15px;
}

.__UIV_SCOPE__ .StarIcon {
  transform: translate(-0px,25px);
  width: 20px;
  fill: #ebd300;
}

.__UIV_SCOPE__ .Stars {
  position: absolute;
  color: white;
  font-size: 15px;
  font-weight: bold;
  transform: translate(80px,-70px);
}

.__UIV_SCOPE__ .GameImg:hover .Descripion {
  opacity: 100%;
}

.__UIV_SCOPE__ .GameImg:hover .Gfooter {
  width: 100%;
  height: 100%;
}

.__UIV_SCOPE__ .GameImg:hover .SmallIcon {
  width: 60px;
  height: 60px;
}

.__UIV_SCOPE__ .GameImg:hover .Name {
  transform: translate(75px,-235px);
}

.__UIV_SCOPE__ .GameImg:hover .GameIcon {
  transform: translate(100px,-160px);
}
